from urls import canonical_url

import pytest


def test_string_input_with_valid_url():
    assert canonical_url('http://EXAMPLE.COM/foo/bar?query=1') == 'http://example.com/foo/bar?query=1'

def test_string_input_with_https_and_fragment():
    assert canonical_url('HTTPS://EXAMPLE.COM/path#frag') == 'https://example.com/path#frag'

def test_non_string_input():
    try:
        canonical_url(None)
        assert False
    except ValueError:
        pass

def test_missing_host():
    try:
        canonical_url('http://')
        assert False
    except ValueError:
        pass

def test_invalid_scheme():
    try:
        canonical_url('ftp://example.com')
        assert False
    except ValueError:
        pass

def test_root_path_handling():
    assert canonical_url('http://example.com/') == 'http://example.com/'

def test_query_preservation():
    assert canonical_url('http://example.com/path?query=1') == 'http://example.com/path?query=1'


def test_trailing_slash_removal():
    assert canonical_url('http://example.com/path/') == 'http://example.com/path'

def test_case_sensitivity():
    assert canonical_url('HTTP://Example.Com') == 'http://example.com'

def test_empty_path():
    assert canonical_url('http://example.com') == 'http://example.com'
